/* SPU initialization and PIO use this 240-iteration delay. The two stack
 * words remain visible to the guest throughout the wait. */
bool nc_credits_spu_wait__stream3_exe_80023094(CPUState *c) {
    if (c->budget <= 6)
        return false;
    R(29) -= 8;
    R(2) = 13;
    c->budget -= 2;
    MEM_W32(R(29) + 4, R(2));
    c->budget--;
    MEM_W32(R(29), 0);
    c->budget -= 3;

    for (;;) {
        load_word__credits_roll__stream3_exe(c, 2, R(29));
        NC_POLL(c, 1);
        set_reg__credits_roll__stream3_exe(c, 2, (s32)R(2) < 240);
        bool again = R(2) != 0;
        NC_POLL(c, 2);
        if (!again)
            break;

        load_word__credits_roll__stream3_exe(c, 3, R(29) + 4);
        NC_POLL(c, 1);
        set_reg__credits_roll__stream3_exe(c, 2, R(3) * 2);
        set_reg__credits_roll__stream3_exe(c, 2, R(2) + R(3));
        MEM_W32(R(29) + 4, R(2));
        NC_POLL(c, 1);
        load_word__credits_roll__stream3_exe(c, 2, R(29));
        NC_POLL(c, 1);
        set_reg__credits_roll__stream3_exe(c, 2, R(2) + 1);
        MEM_W32(R(29), R(2));
        NC_POLL(c, 1);
        load_word__credits_roll__stream3_exe(c, 2,
                                             R(29)); /* the loop test performs a second load */
    }
    set_reg__credits_roll__stream3_exe(c, 29, R(29) + 8);
    NC_POLL(c, 2);
    return true;
}

bool nc_credits_spu_write__stream3_exe_80022DC4(CPUState *c) {
    if (c->budget <= 8 * NC_INSN_CYCLES + NC_LOAD_CYCLES)
        return false;
    c->budget--;
    R(2) = MEM_R32(0x8003A5E8);
    R(29) -= 32;
    c->budget -= NC_LOAD_CYCLES + 1;
    MEM_W32(R(29) + 20, R(17));
    R(17) = R(4); /* source */
    c->budget -= 2;
    MEM_W32(R(29) + 16, R(16));
    R(16) = R(5); /* byte count */
    c->budget -= 2;
    MEM_W32(R(29) + 24, R(31));
    c->budget -= 2;
    if (R(2)) {
        set_reg__credits_roll__stream3_exe(c, 4, R(17));
        R(31) = 0x80022e30;
        R(5) = R(16);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, 0x800227dc); /* _spu_writeByIO */
        set_reg__credits_roll__stream3_exe(c, 2, R(16));
    } else {
        set_reg__credits_roll__stream3_exe(c, 2, 0x80040000);
        R(2) = MEM_R16(0x8003A5E4);
        NC_POLL(c, NC_LOAD_CYCLES);
        set_reg__credits_roll__stream3_exe(c, 5, 0x80040000);
        load_word__credits_roll__stream3_exe(c, 5, 0x8003a5f4);
        set_reg__credits_roll__stream3_exe(c, 4, 2); /* set transfer address */
        R(31) = 0x80022e04;
        R(5) = R(2) << (R(5) & 31);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, 0x80022b34);

        R(31) = 0x80022e0c;
        R(4) = 1; /* select write mode */
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, 0x80022b34);

        set_reg__credits_roll__stream3_exe(c, 4, 3); /* start DMA */
        set_reg__credits_roll__stream3_exe(c, 5, R(17));
        R(31) = 0x80022e1c;
        R(6) = R(16);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, 0x80022b34);
        R(2) = R(16);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
    }
    load_word__credits_roll__stream3_exe(c, 31, R(29) + 24);
    load_word__credits_roll__stream3_exe(c, 17, R(29) + 20);
    load_word__credits_roll__stream3_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream3_exe(c, 29, R(29) + 32);
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    return true;
}

